'use strict';
(() => {
 const TW=45,TH=22.5;
 let c,view,t;
 const iso=(x,y,z=0)=>({x:(x-y)*TW,y:(x+y)*TH-z});
 function poly(points,colour,stroke){c.beginPath();points.forEach((p,i)=>i?c.lineTo(p.x,p.y):c.moveTo(p.x,p.y));c.closePath();c.fillStyle=colour;c.fill();if(stroke){c.strokeStyle=stroke;c.lineWidth=.8;c.stroke();}}
 function tile(x,y,w,h,colour,z=0,stroke){poly([iso(x,y,z),iso(x+w,y,z),iso(x+w,y+h,z),iso(x,y+h,z)],colour,stroke);}
 function line(a,b,colour,width=2){c.strokeStyle=colour;c.lineWidth=width;c.lineCap='round';c.beginPath();c.moveTo(a.x,a.y);c.lineTo(b.x,b.y);c.stroke();}
 function ellipse(x,y,rx,ry,colour,rotation=0){c.fillStyle=colour;c.beginPath();c.ellipse(x,y,rx,ry,rotation,0,Math.PI*2);c.fill();}
 function rect(x,y,w,h,colour,radius=0){c.fillStyle=colour;if(radius){c.beginPath();c.roundRect(x,y,w,h,radius);c.fill();}else c.fillRect(x,y,w,h);}
 function box(x,y,w,h,z,top,front,side,base=0){poly([iso(x+w,y,base),iso(x+w,y+h,base),iso(x+w,y+h,z),iso(x+w,y,z)],side);poly([iso(x,y+h,base),iso(x+w,y+h,base),iso(x+w,y+h,z),iso(x,y+h,z)],front);tile(x,y,w,h,top,z);}
 function label(text,x,y,z=0){const p=iso(x,y,z);c.save();c.font='500 11px "DM Sans",sans-serif';c.textAlign='center';const width=c.measureText(text).width+20;rect(p.x-width/2,p.y-24,width,23,'#fafbf0ed',6);c.fillStyle='#73865b';c.fillText(text,p.x,p.y-8);c.restore();}
 function plant(x,y,size=1,palm=false){const p=iso(x,y);c.save();c.translate(p.x,p.y);c.scale(size,size);ellipse(4,1,17,7,'#4b694621');if(!palm){ellipse(0,-7,13,7,'#b88360');poly([{x:-12,y:-8},{x:12,y:-8},{x:9,y:7},{x:-9,y:7}],'#c79870');ellipse(0,-8,11,5,'#8b7956');for(let i=0;i<7;i++){const angle=i*.9;const lx=Math.sin(angle)*11,ly=-24-Math.cos(angle)*8;line({x:0,y:-8},{x:lx,y:ly},'#8ba272',2);ellipse(lx,ly,6,12,i%2?'#91a97b':'#a7bb8a',angle);} }else{line({x:0,y:0},{x:8,y:-81},'#aa956d',8);line({x:-1,y:0},{x:6,y:-79},'#c3ae84',3);for(let i=0;i<7;i++){c.save();c.translate(7,-82);c.rotate(i*Math.PI/3.5);poly([{x:0,y:0},{x:16,y:-13},{x:48,y:1},{x:18,y:-4}],i%2?'#87a273':'#a2ba86');c.restore();}}c.restore();}
 function steam(x,y,z=0){const p=iso(x,y,z);for(let i=0;i<4;i++){const phase=(t*.65+i*.24)%1;ellipse(p.x+Math.sin(t*2+i)*6,p.y-phase*31,3+phase*5,5+phase*6,`rgba(245,246,231,${.5*(1-phase)})`);}}
 function furniture(p){const x=p.x,y=p.y,w=p.w,h=p.h;
  if(p.type==='bed'){box(x,y,w,h,10,'#c1ad88','#b29a77','#a18f6c');box(x+.05,y+.05,w-.1,h-.1,20,'#f2e8d2','#d9cfb6','#c4bca4',10);box(x,y,w,.18,44,'#b89c76','#b9a27e','#aa906d');tile(x+.08,y+.8,w-.16,h-.9,'#9eb69b',21);for(let i=0;i<2;i++){const a=iso(x+.25+i*(w*.45),y+.33,23);ellipse(a.x,a.y,17,9,'#faf6e9',.4);}line(iso(x+.1,y+1,22),iso(x+w-.1,y+1,22),'#d4e0bf',3);}
  else if(p.type==='sofa'||p.type==='bench'){const sofa=p.type==='sofa';box(x,y,w,h,17,sofa?'#c38e75':'#c4ae84',sofa?'#ba7f67':'#b09a72',sofa?'#a96f59':'#978a67');box(x,y,w,.18,40,sofa?'#d3a18a':'#bdab85',sofa?'#c18a74':'#bda983','#9f8e6b');for(let i=0;i<Math.ceil(w);i++)tile(x+.1+i*(w-.2)/Math.ceil(w),y+.25,(w-.25)/Math.ceil(w),h-.3,sofa?'#d9ab91':'#c7c7a2',19);box(x,y,.15,h,28,sofa?'#c7927b':'#b49e78','#ab7f65','#987f5e');box(x+w-.15,y,.15,h,28,sofa?'#c7927b':'#b49e78','#ab7f65','#987f5e');}
  else if(p.type==='chair'){box(x,y,w,h,17,'#acbc94','#8eaa7c','#7d9770');box(x,y,w,.14,40,'#a2b489','#91a87d','#81966e');for(const dx of [.1,w-.18])line(iso(x+dx,y+h-.1,14),iso(x+dx,y+h-.1),'#857b5e',4);}
  else if(['desk','table','cafe-table'].includes(p.type)){const z=p.type==='desk'?32:27;for(const dx of [.12,w-.12])for(const dy of [.12,h-.12])line(iso(x+dx,y+dy),iso(x+dx,y+dy,z),'#a58e68',4);box(x,y,w,h,z,'#d1b98f','#bba179','#a28e68',z-5);const a=iso(x+w*.35,y+h*.45,z+2);if(p.type==='desk'){poly([{x:a.x-12,y:a.y},{x:a.x,y:a.y-6},{x:a.x+12,y:a.y},{x:a.x,y:a.y+6}],'#efead2');line({x:a.x,y:a.y-5},{x:a.x,y:a.y+5},'#c5c8ab',1);}else{ellipse(a.x,a.y,11,6,'#ece5c9');ellipse(a.x,a.y-2,6,3,'#b79f6b');const cup=iso(x+w*.65,y+h*.3,z+3);ellipse(cup.x,cup.y,6,3,'#f6f0dc');rect(cup.x-5,cup.y-7,10,7,'#efe6cc',2);ellipse(cup.x,cup.y-7,5,2.5,'#a38b63');}}
  else if(p.type==='shelf'){box(x,y,w,h,82,'#b5a180','#bbab8b','#a08f6f');for(let level=12;level<78;level+=22){tile(x+.08,y+h-.1,w-.16,.08,'#dccbaa',level);for(let book=.12;book<w-.08;book+=.22){const a=iso(x+book,y+h+.01,level+13),b=iso(x+book+.13,y+h+.01,level);poly([a,iso(x+book+.13,y+h+.01,level+13),b,iso(x+book,y+h+.01,level)],['#9cac86','#c19a7a','#d5c5a0','#7e9a90'][Math.floor(book*10+level)%4]);}}}
  else if(p.type==='plant')plant(x+w*.5,y+h*.5,.9);
  else if(p.type==='lamp'){const a=iso(x+w*.5,y+h*.5);ellipse(a.x,a.y,13,7,'#d6cbaa');line(a,{x:a.x,y:a.y-61},'#9b9475',3);poly([{x:a.x-10,y:a.y-68},{x:a.x+10,y:a.y-68},{x:a.x+18,y:a.y-47},{x:a.x-18,y:a.y-47}],'#e3d6ab');ellipse(a.x,a.y-47,18,5,'#eee4bf');}
  else if(p.type==='kitchen'||p.type==='counter'){box(x,y,w,h,32,'#d8ccb0','#b8ba99','#9fab8e');for(let dx=.1;dx<w;dx+=.8)line(iso(x+dx,y+h+.005,1),iso(x+dx,y+h+.005,29),'#9ba98b',1);const a=iso(x+w*.5,y+h*.45,33);ellipse(a.x,a.y,12,6,'#718778');ellipse(a.x,a.y-4,10,5,'#4f6c5b');line({x:a.x+7,y:a.y-3},{x:a.x+20,y:a.y-9},'#8d8d6f',4);if(view.pose==='cook'||view.pose==='cafe-work')steam(x+w*.5,y+h*.45,43);if(p.type==='counter'){box(x+w-.7,y+.2,.5,.5,52,'#c0c7ab','#8faaa0','#76948a',32);const cup=iso(x+.7,y+h*.6,36);ellipse(cup.x,cup.y,9,5,'#eee8cc');rect(cup.x-6,cup.y-10,12,10,'#f1e9ce',3);}}
  else if(p.type==='shower'){tile(x,y,w,h,'#b9cfc3',2,'#e1ede0');const a=iso(x+.1,y+.1,91);line(iso(x+.1,y+.1,0),a,'#9db7aa',3);line(a,iso(x+w-.1,y+.1,91),'#9db7aa',3);poly([iso(x,y,8),iso(x+w,y,8),iso(x+w,y,88),iso(x,y,88)],'#c3ddd05c');poly([iso(x+w,y,8),iso(x+w,y+h,8),iso(x+w,y+h,88),iso(x+w,y,88)],'#cce4da4d');const shower=iso(x+.4,y+.4,81);ellipse(shower.x,shower.y,10,4,'#a8beb0');if(view.pose==='shower')for(let i=0;i<12;i++){const dy=((t*75+i*9)%67);line({x:shower.x-8+(i%5)*4,y:shower.y+dy},{x:shower.x-8+(i%5)*4,y:shower.y+dy+5},'#a0cbd0',1.6);}}
  else if(p.type==='lounger'){for(const dx of [.1,w-.15])line(iso(x+dx,y+.15),iso(x+dx,y+h-.1),'#a18f6d',3);box(x,y+.55,w,h-.55,13,'#d6c396','#c2b082','#ac9c74');poly([iso(x,y+.55,13),iso(x+w,y+.55,13),iso(x+w,y,35),iso(x,y,35)],'#e7d9b2');for(let i=0;i<4;i++)tile(x+i*w/4,y+.6,w/8,h-.7,'#b7c7a2',14);}
  else if(p.type==='dock'){box(x,y,w,h,6,'#c9b58c','#b19f78','#a3916f');for(let i=0;i<w;i+=.3)line(iso(x+i,y,7),iso(x+i,y+h,7),'#b29e76',1);for(let i=0;i<3;i++){const ax=x+.2+i*w/2;line(iso(ax,y,.5),iso(ax,y,31),'#a9a080',4);line(iso(ax,y,31),iso(Math.min(ax+w/2,x+w),y,31),'#d8c8a3',2);}}
  else if(p.type==='market-stall'){box(x,y,w,h,27,'#ccba8b','#bca87b','#a99970');for(let n=0;n<6;n++){const a=iso(x+.35+n*(w-.6)/6,y+h*.6,31);ellipse(a.x,a.y,8,5,['#b8bd7e','#d5a074','#d8c984'][n%3]);}for(const dx of [.08,w-.08])line(iso(x+dx,y+.1),iso(x+dx,y+.1,85),'#a99c77',4);for(let i=0;i<8;i++)tile(x+i*w/8,y,w/8,h+1.1,i%2?'#ece1b8':'#bd9370',82);line(iso(x,y+h+1.1,82),iso(x+w,y+h+1.1,82),'#b79d75',3);}
  else if(p.type==='crate'){box(x,y,w,h,26,'#c6ad80','#baa073','#a58f68');for(let z=7;z<26;z+=8)line(iso(x,y+h,z),iso(x+w,y+h,z),'#e1c99e',2);}
 }
 function head(x,y,asleep=false){ellipse(x,y,8.5,10,'#b78661');c.fillStyle='#485444';c.beginPath();c.arc(x,y-3,8.8,Math.PI,Math.PI*2);c.fill();ellipse(x-6,y-6,3,4,'#485444');if(asleep){line({x:x+1,y:y+1},{x:x+5,y:y+1},'#574c38',1.2);}else ellipse(x+4,y+.5,1.2,1.4,'#4d5039');}
 function avatar(x,y,pose='idle',phase=0,colour='#cb956a',small=false){const water=view.type==='beach'&&x>=5.5&&!['fish','sunbathe','sit'].includes(pose);if(water&&['idle','walk','jog'].includes(pose))pose='swim';const p=iso(x,y);c.save();c.translate(p.x,p.y);if(small)c.scale(.85,.85);const stride=Math.sin(phase*9),sway=Math.sin(phase*2)*1.4;
  if(pose==='swim'){if(view.heading.x-view.heading.y<0)c.scale(-1,1);c.rotate(.13);for(let i=0;i<3;i++)ellipse(-i*14-4,1+Math.sin(phase*3+i),18-i*2,4+i*.6,'#b5ded24d');c.strokeStyle='#ebf6df99';c.lineWidth=1.2;c.beginPath();c.ellipse(-2,2,32,9,0,0,Math.PI*2);c.stroke();ellipse(-9,0,21,7,'#729e98');line({x:-19,y:0},{x:-33,y:5+stride*5},'#a37c5f',4);line({x:-19,y:1},{x:-34,y:-3-stride*4},'#a37c5f',4);line({x:1,y:-1},{x:14,y:-15-stride*10},'#ba8b66',4);line({x:-3,y:2},{x:5,y:10+stride*6},'#ba8b66',4);head(12,-6,false);poly([{x:-24,y:2},{x:28,y:2},{x:23,y:8},{x:-30,y:6}],'#8dbdbb70');for(let i=0;i<3;i++){const f=(phase*1.4+i*.3)%1;ellipse(17+f*14,3-f*15,1.4,2,'#e4f2dd99');}c.restore();return;}
  if(['sleep','sunbathe'].includes(pose)){c.rotate(.32);ellipse(0,0,35,10,'#5a715018');line({x:2,y:-4},{x:29,y:-2},'#7f9984',10);line({x:2,y:3},{x:30,y:6},'#90a88e',9);rect(-10,-12,28,18,pose==='sleep'?'#b4c8a6':'#d7b27b',7);line({x:-7,y:-8},{x:8,y:-3},'#ba8b64',4);head(-19,-9,true);if(pose==='sleep'){c.fillStyle='#8aa67a';c.font='12px Manrope,sans-serif';for(let i=0;i<3;i++){const f=(phase*.3+i*.3)%1;c.globalAlpha=1-f;c.fillText(i===2?'Z':'z',-21+f*12,-30-f*27);}c.globalAlpha=1;}else{rect(-25,-12,13,4,'#5c715b',2);}c.restore();return;}
  const seated=['sit','read','eat','fish'].includes(pose),rootY=0;ellipse(1,1,12,5,'#47683c21');c.translate(0,rootY+sway*.2);if(seated){line({x:-4,y:-15},{x:-3,y:0},'#657c6b',6);line({x:-3,y:0},{x:8,y:9},'#657c6b',5);line({x:4,y:-14},{x:11,y:-1},'#708774',6);line({x:11,y:-1},{x:20,y:6},'#708774',5);line({x:7,y:9},{x:14,y:9},'#4e6655',4);line({x:19,y:6},{x:25,y:6},'#4e6655',4);}else{const gait=['walk','jog','tidy','market-work','cafe-work'].includes(pose)?stride:0;line({x:-4,y:-18},{x:-6-gait*6,y:-1},'#637c69',6);line({x:4,y:-18},{x:7+gait*6,y:-1},'#728974',6);line({x:-6-gait*6,y:-1},{x:-1-gait*6,y:0},'#4e6452',4);line({x:7+gait*6,y:-1},{x:13+gait*6,y:0},'#4e6452',4);}
  c.save();if(pose==='dance')c.rotate(Math.sin(phase*4)*.12);rect(-9,-39,19,24,pose==='shower'?'#91b6ad':colour,6);head(1,-50,false);const arm='#b88a64';if(pose==='dance'||pose==='stretch'){const lift=pose==='dance'?Math.sin(phase*5)*8:Math.sin(phase*.8)*4;line({x:-8,y:-33},{x:-18,y:-47+lift},arm,5);line({x:-18,y:-47+lift},{x:-12,y:-63+lift},arm,4);line({x:10,y:-34},{x:24,y:-44-lift},arm,5);line({x:24,y:-44-lift},{x:20,y:-62-lift},arm,4);if(pose==='dance'){c.fillStyle='#9aac7c';c.font='17px Georgia';c.fillText('♪',28+Math.sin(phase)*5,-54);c.fillText('♫',-35,-64+Math.cos(phase*2)*5);}}
  else if(pose==='read'){line({x:-7,y:-32},{x:-13,y:-18},arm,5);line({x:9,y:-32},{x:22,y:-22},arm,5);poly([{x:-17,y:-25},{x:2,y:-20},{x:20,y:-28},{x:20,y:-12},{x:2,y:-7},{x:-17,y:-12}],'#f0ead0');line({x:2,y:-20},{x:2,y:-7},'#b9c2a1',1);line({x:-11,y:-19},{x:-3,y:-16},'#c3c8ae',1);line({x:8,y:-20},{x:15,y:-23},'#c3c8ae',1);}
  else if(pose==='eat'){line({x:-6,y:-31},{x:1,y:-16},arm,4);ellipse(4,-17,12,5,'#efe4c4');ellipse(4,-20,9,3,'#c8ac73');const lift=Math.sin(phase*3)*7;line({x:10,y:-32},{x:18,y:-22-lift},arm,4);line({x:18,y:-22-lift},{x:8,y:-37-lift*.3},'#a7ad8d',2);}
  else if(pose==='fish'){line({x:9,y:-31},{x:22,y:-20},arm,5);line({x:22,y:-20},{x:56,y:-76},'#a28f66',2);c.strokeStyle='#c0c8a1';c.lineWidth=1;c.beginPath();c.moveTo(56,-76);c.quadraticCurveTo(87,-60,99,13+Math.sin(phase*2)*3);c.stroke();ellipse(99,13+Math.sin(phase*2)*3,3,2,'#c3956b');if(Math.sin(phase*1.6)>.65){c.save();c.translate(94,-10-Math.sin(phase*1.6)*15);ellipse(0,0,9,4,'#9fbeb1',-.5);poly([{x:-7,y:0},{x:-13,y:-4},{x:-12,y:5}],'#8baea1');c.restore();}}
  else if(pose==='tidy'){line({x:-6,y:-31},{x:8,y:-19},arm,5);line({x:9,y:-30},{x:17+stride*4,y:-15},arm,4);line({x:19+stride*4,y:-36},{x:28+stride*8,y:9},'#b19a6e',3);poly([{x:22+stride*8,y:4},{x:34+stride*8,y:3},{x:41+stride*8,y:12},{x:20+stride*8,y:15}],'#c9b884');for(let i=0;i<4;i++)ellipse(29+stride*8+i*5,16-i,1,1,'#a7b18b');}
  else if(pose==='cook'||pose==='cafe-work'){line({x:-7,y:-32},{x:-12,y:-20},arm,4);line({x:10,y:-32},{x:24+Math.sin(phase*5)*5,y:-22},arm,5);line({x:24+Math.sin(phase*5)*5,y:-22},{x:32+Math.sin(phase*5)*6,y:-32},'#b7a77b',2.5);}
  else if(pose==='market-work'){line({x:-7,y:-32},{x:-7,y:-17},arm,4);line({x:10,y:-32},{x:21,y:-18},arm,4);rect(-10,-24,33,18,'#c7ae7e',2);line({x:-8,y:-18},{x:21,y:-18},'#e0c69b',2);}
  else{line({x:-8,y:-33},{x:-12+stride*2,y:-17},arm,4);line({x:10,y:-33},{x:15-stride*2,y:-16},arm,4);}c.restore();
  if(pose==='shower'){for(let i=0;i<8;i++){const dy=(phase*72+i*11)%67;line({x:-12+i*4,y:-76+dy},{x:-11+i*4,y:-71+dy},'#a6d2d0',1.5);}ellipse(0,-2,18,5,'#c8e4da60');}c.restore();
 }
 function walls(){const cols=view.cols,rows=view.rows,colour=state.roomStyle==='sea'?'#cbdcd2':state.roomStyle==='sage'?'#d9dfc5':'#e7ddc7';poly([iso(0,0),iso(cols,0),iso(cols,0,112),iso(0,0,112)],colour);poly([iso(0,0),iso(0,rows),iso(0,rows,112),iso(0,0,112)],state.roomStyle==='sea'?'#bacfc2':state.roomStyle==='sage'?'#c8d4b4':'#d8cdb5');line(iso(0,rows,1),iso(0,0,1),'#c0b593',5);line(iso(0,0,1),iso(cols,0,1),'#d0c4a3',5);const wx=cols*.45,wy=0;poly([iso(wx,wy,45),iso(wx+2.1,wy,45),iso(wx+2.1,wy,101),iso(wx,wy,101)],'#f6efda');poly([iso(wx+.12,wy-.015,50),iso(wx+1.98,wy-.015,50),iso(wx+1.98,wy-.015,96),iso(wx+.12,wy-.015,96)],'#c1d8cd');line(iso(wx+1.05,wy-.025,50),iso(wx+1.05,wy-.025,96),'#eee8cf',4);line(iso(wx+.12,wy-.025,72),iso(wx+1.98,wy-.025,72),'#eee8cf',3);poly([iso(wx-.15,0,38),iso(wx+.2,0,38),iso(wx+.27,0,103),iso(wx-.1,0,103)],'#b3bf9d');poly([iso(wx+1.95,0,38),iso(wx+2.3,0,38),iso(wx+2.22,0,103),iso(wx+2.05,0,103)],'#adb996');const frame=iso(0,rows*.43,75);c.save();c.translate(frame.x,frame.y);poly([{x:0,y:0},{x:-25,y:12},{x:-25,y:-20},{x:0,y:-32}],'#af9872');poly([{x:-4,y:-3},{x:-22,y:6},{x:-22,y:-17},{x:-4,y:-26}],'#e2d7b7');c.restore();}
 function floor(){const n=view.cols,m=view.rows;if(view.type==='beach'){tile(0,0,n,m,'#9fc9c5');for(let x=0;x<6;x++)for(let y=0;y<m;y++)tile(x,y,1,1,(x+y)%3?'#e5d2aa':'#e8d7b1');for(let y=0;y<m;y+=.18){const x=5.6+Math.sin(y*1.4+t*.7)*.15;line(iso(x,y,.6),iso(x,y+.19,.6),'#f2f0d0b0',4);}for(let i=0;i<55;i++){const x=6.2+(i*1.73)%5.4,y=(i*2.41)%m,p=iso(x,y);line({x:p.x+Math.sin(t+i)*3,y:p.y},{x:p.x+11+Math.sin(t+i)*3,y:p.y},i%3?'#c0dfd17a':'#e3efdb99',1.2);}for(const y of [2.2,5.9]){line(iso(6.7,y),iso(10.6,y),'#d8e8c98c',1);for(let x=6.7;x<10.7;x+=.8){const p=iso(x,y);ellipse(p.x,p.y+Math.sin(t*2+x)*1.5,3,2,'#e4c98e');}}return;}
  box(0,0,n,m,0,'#d4c3a0','#b9a988','#a79b7e',-8);for(let x=0;x<n;x++)for(let y=0;y<m;y++){tile(x,y,1,1,view.type==='library'?'#d5d7bc':view.type==='cafe'?'#ddd2b6':view.type==='market'?'#d3d4b5':(x+y)%4===0?'#d7c29b':'#dfcda8',.1,'#c3ad8650');if(view.type==='home')for(let q=1;q<3;q++)line(iso(x+q/3,y,.3),iso(x+q/3,y+1,.3),'#e9d8b422',.7);}walls();if(view.type==='home'){tile(n-2.2,m-1.1,1.1,.65,'#b4bc95',.5);for(let i=0;i<6;i++)line(iso(n-2.15+i*.17,m-1.1,1),iso(n-2.15+i*.17,m-.45,1),'#d6d7b3',1);}if(view.type==='cafe'){tile(2,2.6,4,3,'#b5c2a047',.5);}}
 function beachDetails(){const p=iso(3.1,1.4,75);line(iso(3.1,1.4),p,'#b69f73',3);for(let i=0;i<8;i++){const angle=i*Math.PI/4,next=(i+1)*Math.PI/4;poly([{x:p.x,y:p.y-12},{x:p.x+Math.cos(angle)*36,y:p.y+Math.sin(angle)*17},{x:p.x+Math.cos(next)*36,y:p.y+Math.sin(next)*17}],i%2?'#e4d3aa':'#b8c7a1');}const boat=iso(11.2,7.4);c.save();c.translate(boat.x,boat.y+Math.sin(t)*2);poly([{x:-24,y:0},{x:23,y:0},{x:13,y:10},{x:-17,y:9}],'#d8dbc0');line({x:-2,y:0},{x:-2,y:-52},'#a8bba9',2);poly([{x:1,y:-48},{x:1,y:-5},{x:26,y:-5}],'#eee9cf');c.restore();}
 function draw(viewState,canvas,time){view=viewState;t=time;c=canvas.getContext('2d');const bounds=canvas.getBoundingClientRect(),width=bounds.width,height=bounds.height;if(!width||!height)return;const dpr=Math.min(2,devicePixelRatio||1);if(canvas.width!==Math.round(width*dpr)||canvas.height!==Math.round(height*dpr)){canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);}c.setTransform(dpr,0,0,dpr,0,0);c.clearRect(0,0,width,height);const gradient=c.createLinearGradient(0,0,width,height);gradient.addColorStop(0,view.type==='beach'?'#e7eedf':'#edf0e4');gradient.addColorStop(1,view.type==='beach'?'#c7dfd1':'#dce5d2');rect(0,0,width,height,gradient);const scale=Math.min((width-60)/((view.cols+view.rows)*TW),(height-60)/((view.cols+view.rows)*TH+135))*view.zoom,focus=view.zoom>1.15?iso(view.actor.x,view.actor.y,15):iso(view.cols/2,view.rows/2,22),targetX=width*.5-focus.x*scale,targetY=height*.55-focus.y*scale;const prior=view.camera;view.camera={scale,ox:prior&&view.zoom>1.15?prior.ox+(targetX-prior.ox)*.22:targetX,oy:prior&&view.zoom>1.15?prior.oy+(targetY-prior.oy)*.22:targetY};c.save();c.translate(view.camera.ox,view.camera.oy);c.scale(scale,scale);floor();if(view.type==='beach')beachDetails();const objects=view.props.filter(p=>p.type!=='swim-zone').map(p=>({depth:p.x+p.y+(p.w+p.h)/2,draw:()=>p.type==='palm'?plant(p.x+p.w/2,p.y+p.h/2,1.1,true):furniture(p)}));const moving=view.route.length>0,pose=scenePose(view,moving);const actorZ=pose==='sleep'?25:pose==='sunbathe'?14:['sit','read','eat','fish'].includes(pose)?2:0;objects.push({depth:view.actor.x+view.actor.y+.12,draw:()=>{if(['read','eat'].includes(pose)&&!['bench','sofa','chair'].includes(view.current?.target.prop?.type))box(view.actor.x-.28,view.actor.y-.2,.56,.45,15,'#c7b28b','#b19d75','#a28f6b');c.save();c.translate(0,-actorZ);avatar(view.actor.x,view.actor.y,pose,time);c.restore();}});if(view.type==='cafe'){objects.push({depth:8.8,draw:()=>avatar(6.4,2.4,'read',time*.6,'#8fa58b',true)});}if(view.type==='market'){objects.push({depth:2.7,draw:()=>avatar(2,.7,'cafe-work',time*.5,'#a0ad8a',true)});}objects.sort((a,b)=>a.depth-b.depth).forEach(o=>o.draw());for(const p of view.props){if(!p.action)continue;const near=Math.hypot(view.actor.x-p.x-p.w/2,view.actor.y-p.y-p.h/2)<2.4;if(view.hover===p.id||near&&!view.current)label(p.type==='swim-zone'?'Take a dip':ACTIVITIES[p.action]?.name||'Use',p.x+p.w/2,p.y+p.h/2,p.type==='market-stall'?110:p.type==='shelf'?100:65);}const avatarPoint=iso(view.actor.x,view.actor.y,72+actorZ);if(!view.current){ellipse(avatarPoint.x,avatarPoint.y,4,4,'#f8f3dd');ellipse(avatarPoint.x,avatarPoint.y,1.7,1.7,'#c18e62');}c.restore();if(state.minutes>1140||state.minutes<360){c.globalAlpha=.07;rect(0,0,width,height,'#465d78');c.globalAlpha=1;}c.setTransform(dpr,0,0,dpr,0,0);}
 function scenePose(v,moving){if(v.current?.started)return v.pose;if(moving)return 'walk';return 'idle';}
 function pick(v,canvas,clientX,clientY){const r=canvas.getBoundingClientRect(),camera=v.camera;if(!camera)return {};const sx=(clientX-r.left-camera.ox)/camera.scale,sy=(clientY-r.top-camera.oy)/camera.scale,point={x:(sx/TW+sy/TH)/2,y:(sy/TH-sx/TW)/2};const candidates=v.props.filter(p=>p.action).map(p=>{const height=p.type==='market-stall'?60:p.type==='shelf'?40:p.type==='swim-zone'?0:15;const center=iso(p.x+p.w/2,p.y+p.h/2,height);return {prop:p,distance:Math.hypot((sx-center.x)/Math.max(25,(p.w+p.h)*TW*.26),(sy-center.y)/Math.max(24,(p.w+p.h)*TH*.3))};}).filter(p=>p.distance<1).sort((a,b)=>a.distance-b.distance);return {point,prop:candidates[0]?.prop||null};}
 window.KoraSceneArt={draw,pick};
})();
